mapper.select:
SELECT sal.audit_id AS auditId, DATE_FORMAT(sal.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, sal.sales_user_id AS salesUserId, su.name AS employeeName, cc.code_name AS actionName, CASE WHEN sal.target_customer_id IS NOT NULL THEN CONCAT('CUST-', sal.target_customer_id) ELSE NULL END AS customerFormattedId, COALESCE(pc.name, ic.name) AS customerName, sal.ip_address AS ipAddress FROM system_audit_log sal LEFT JOIN sales_user su ON sal.sales_user_id = su.id LEFT JOIN common_code cc ON cc.group_code = 'AUDIT_ACTION' AND cc.code_value = sal.action_type_code LEFT JOIN potential_customer pc ON sal.target_customer_id = pc.id LEFT JOIN integrated_customer ic ON sal.target_customer_id = ic.integrated_customer_id
AND sal.created_at >= STR_TO_DATE(CONCAT(#{request.startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
AND sal.created_at <= STR_TO_DATE(CONCAT(#{request.endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')
AND sal.action_type_code = #{request.actionTypeCode}
ORDER BY sal.created_at DESC, sal.audit_id DESC LIMIT #{request.safeSize} OFFSET #{request.offset}
